import{z as B,x as p,o as E,c as A,q as n,j as i,D as t,d as l,s,S as o,b as e}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"动态采样","description":"","frontmatter":{"title":"动态采样","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/dynamic-sampling-rl.md","filePath":"llm/dynamic-sampling-rl.md","lastUpdated":1791063341000}'),d={name:"llm/dynamic-sampling-rl.md"};function m(h,a,c,D,f,b){const r=p("Mermaid");return E(),A("div",null,[a[2]||(a[2]=n('<h1 id="动态采样" tabindex="-1">动态采样 <a class="header-anchor" href="#动态采样" aria-label="Permalink to &quot;动态采样&quot;">​</a></h1><div class="epigraph"><p>全对或全错的组没有相对梯度；滤掉它们、过采样直到 batch 有信号，是目标定义的一部分，不是可选技巧。</p><footer>—— Yu 等 DAPO 的 Dynamic Sampling；约束写在目标的 s.t. 里</footer></div><p><a href="/llm/overlong-filtering">上一课</a>处理截断标签。即使长度健康，<a href="/llm/grpo">GRPO</a> 仍会在准确率为 0 或 1 的题上得到零优势。缺口是：<strong>有效 batch 随训练变瘦，更新浪费在无信号组上。</strong> DAPO 的动态采样要求 \\(0\\lt |\\{o_i:\\text{答对}\\}|\\lt G\\)，buffer 未满就继续采。本课写这一约束。消融上它把分数从 42 推到 50，是四件套里最大的一块。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>组内标准化在 \\(\\mathrm{std}=0\\) 时要么 NaN，要么 \\(\\hat A=0\\)。训练后期易题全对、难题全错，两种组变多。继续更新等于空转，还可能被数值噪声推动。静态题库 + 固定 \\(G\\) 无法保证每步都有相对信号。动态采样改变的是<strong>进入梯度的题分布</strong>：变难、变「当前策略仍会分叉」的题。</p><p><span class="marginnote">直觉类比：把「组」想成同一道题让模型考 8 次——8 次全对或全交白卷，老师看不出「哪种写法更好」，没有可比较的信息；只有对错掺半时，才能把答对的写法推高、答错的压低，这就是「相对优势」。</span></p><p>这不是普通的难度课程（后课）。课程按预设难度排序；动态采样按<strong>当前通过率</strong>过滤，同一题会在策略变好后从有信号变成全对再被滤掉。</p><h3 id="墙钟直觉经常是反的" tabindex="-1">墙钟直觉经常是反的 <a class="header-anchor" href="#墙钟直觉经常是反的" aria-label="Permalink to &quot;墙钟直觉经常是反的&quot;">​</a></h3><p>多滤几条似乎更贵。DAPO 原文图显示总时间可以下降：少做无效更新，收敛更快。但题库整体过难、通过率长期接近 0 时，会一直采不到满 batch，墙钟爆炸。必须有超时与回退（降低难度、升温、暂时允许部分零梯度）。</p><p><span class="marginnote">\\(G=1\\) 时相对优势未定义，动态采样救不了，应改 PPO 或 REINFORCE++。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对每个 prompt 采 \\(G\\) 条、算 \\(R\\)。若全 0 或全 1，丢弃该 prompt，从队列再取。凑满训练 batch 再更新。过采样上限要设：同一 prompt 不要无限重采。统计：丢弃率、为满 batch 额外生成的倍数、各难度的存活率。奖励必须是可比较的对错；高噪声 RM 上「全对」没有意义，动态采样会滤掉的是「分数碰巧相同」，可能删掉有用的序信息。</p><p><span class="marginnote">常见误区：以为「分数碰巧相同」就等于「没有信息」。两个答案同拿 0.7 分，可能一个论证扎实、一个碰运气——硬过滤把这个有用的序信息一起删了。动态采样因此最适合对错分明的 0/1 奖励，连续分数上要三思。</span></p><p><span class="marginnote">数字实例：\\(G=8\\) 时，一道通过率 50% 的题 8 条全对的概率约 \\(0.5^8\\approx 0.4\\%\\)；而通过率 95% 的易题全对概率约 \\(0.95^8\\approx 66\\%\\)。训练后期大量 batch 名额被这种「送分题全对组」占掉再丢弃——这就是有效 batch 变瘦的账。</span></p>',14)),(E(),i(o,null,{default:t(()=>[s(r,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20TD%0A%20%20P%5B%22%E9%A2%98%20x%22%5D%20--%3E%20G%5B%22%E9%87%87%20G%20%E6%9D%A1%22%5D%0A%20%20G%20--%3E%20R%5B%22%E7%BB%84%E5%86%85%20R%22%5D%0A%20%20R%20--%3E%20CHK%7B%220%20%EF%BC%9C%20%E7%AD%94%E5%AF%B9%E6%95%B0%20%EF%BC%9C%20G%22%7D%0A%20%20CHK%20--%3E%7C%E5%90%A6%7C%20DROP%5B%22%E4%B8%A2%E5%BC%83%EF%BC%8C%E5%86%8D%E9%87%87%E6%A0%B7%22%5D%0A%20%20CHK%20--%3E%7C%E6%98%AF%7C%20BUF%5B%22%E8%BF%9B%E5%85%A5%E8%AE%AD%E7%BB%83%20batch%22%5D%0A%20%20BUF%20--%3E%20UPD%5B%22GRPO%20%2F%20DAPO%20%E6%9B%B4%E6%96%B0%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,"与熵正则正交：有熵仍可能全对（换词同对）。动态采样看的是奖励方差，不是 token 熵。",-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[l("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,"过滤把梯度集中在决策边界附近的题，类似主动学习。策略被推着去啃「刚刚会一点」的题，通过率曲线更陡。副作用：过易与过难题在更新里消失，评测若含这两端，会表现为「训练指标很好、评测两端差」。应保留一份不过滤的评测集。",-1)),(E(),i(o,null,{default:t(()=>[s(r,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20LR%0A%20%20P0%5B%22%E5%85%A8%E9%94%99%E7%BB%84%20p%3D0%22%5D%20--%3E%20F%5B%22%E8%A2%AB%E8%BF%87%E6%BB%A4%EF%BC%9A%E9%9B%B6%E6%A2%AF%E5%BA%A6%22%5D%0A%20%20P1%5B%22%E5%85%A8%E5%AF%B9%E7%BB%84%20p%3D1%22%5D%20--%3E%20F%0A%20%20PM%5B%22%E9%83%A8%E5%88%86%E5%AF%B9%20p%20%E5%9C%A8%200%20%E4%B8%8E%201%20%E4%B9%8B%E9%97%B4%22%5D%20--%3E%20S%5B%22%E7%BB%84%E5%86%85%E6%9C%89%E5%88%86%E5%8F%89%3Cbr%3E%E4%BA%A7%E7%94%9F%E7%9B%B8%E5%AF%B9%E4%BC%98%E5%8A%BF%22%5D%0A%20%20S%20--%3E%20L%5B%22%E6%A2%AF%E5%BA%A6%E9%9B%86%E4%B8%AD%E5%9C%A8%E5%86%B3%E7%AD%96%E8%BE%B9%E7%95%8C%E9%99%84%E8%BF%91%22%5D%0A%20%20L%20--%3E%20SIDE%5B%22%E8%BF%87%E6%98%93%E4%B8%8E%E8%BF%87%E9%9A%BE%E9%A2%98%E9%80%80%E5%87%BA%E6%9B%B4%E6%96%B0%3Cbr%3E%E8%AF%84%E6%B5%8B%E4%B8%A4%E7%AB%AF%E8%A6%81%E5%8D%95%E7%8B%AC%E7%9B%AF%22%5D%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[l(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=n('<p><span class="marginnote">这张图回答「过滤为什么等于主动学习」：零信号的两端被剪掉后，每一步更新都花在「模型刚刚会一点」的题上，通过率曲线因此更陡；代价是两端题目退出训练分布，评测要另设防线。</span></p><p><span class="marginnote">约束写进目标，复现时关掉动态采样就不是 DAPO。社区 fork 常关它，分数不要写成官方 50。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>偏好 RM、连续分数很少出现精确全同，动态采样几乎不触发，本课主要服务 <a href="/llm/verifiable-reward">可验证奖励</a>。代码沙箱贵时，丢弃组的成本更高，要先用便宜的静态过滤（太易太难题移出题库）再动态采。下一课无 KL：动态采样提供的边界题，正是策略需要离开 SFT 的地方。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>全 0 / 全 1 组无相对梯度；动态采样过采样直到组内有分叉。</li><li>它按当前通过率过滤，不同于预设难度课程。</li><li>题库过难会采不满 batch；必须有超时回退。</li><li>主场是可验证 0/1；高噪声 RM 上慎用。</li><li>出处：Yu 等 DAPO Dynamic Sampling。</li></ul>',6))])}const F=B(d,[["render",m]]);export{u as __pageData,F as default};
